
const request = require('request');
const parser = require('node-feedparser');

class RSS{
    constructor(props){

        this.rssList = props.url;
        if(!this.rssList){
            throw new Error('URL不能为空!');
        }
        if(typeof this.rssList == 'string'){
            this.rssList =[this.rssList];
        }
        this.onChange = props.onChange || (() => {});
        this.onError = props.onError || (() => {});
        this.request();
        
    }
   
    request(){
        let pormiseArr = this.rssList.map((item,index)=>{         
            return this.toPromise(item);
        });
        Promise.all(pormiseArr).then((post)=>{
            this.onChange(post);
        }).catch((error)=>{
            this.onError(error);
        });
    }
    toPromise(item){
        let promise = new Promise((resolve, reject)=>{
            request(item,(error,response,body)=>{
                if(error){
                    reject(error);
                }else{
                    let resp = parser(body, (error,ret)=>{
                        if(error){
                            reject(error);
                        }else{
                            resolve(ret);

                        }
                    })
                }
            })
        });
        return promise;

    }
};

module.exports = (props) => new RSS(props);